from fractions import Fraction as F
import re

def tokens(expr):
    expr = expr.replace("−", "-").replace("–", "-").replace("x", "×").replace("/", "÷")
    return re.findall(r"\d+|[+\-×÷]", expr)

def bodmas(toks):
    """Division and multiplication left to right, then addition and subtraction left to right."""
    out = [F(toks[0])]
    for op, n in zip(toks[1::2], toks[2::2]):
        n = F(n)
        if op == "×":
            out[-1] *= n
        elif op == "÷":
            out[-1] /= n
        else:
            out += [op, n]
    val = out[0]
    for op, n in zip(out[1::2], out[2::2]):
        val = val + n if op == "+" else val - n
    return val

def swap_signs(toks, pairs):
    m = {}
    for a, b in pairs:
        m[a], m[b] = b, a
    return [m.get(t, t) for t in toks]

def solve(expr, pairs, options):
    val = bodmas(swap_signs(tokens(expr), pairs))
    return [k for k, v in options.items() if F(v) == val]

