# cross-check against Python's own precedence on random expressions
import random
random.seed(0)
for _ in range(500):
    toks = [str(random.randint(1, 50))]
    for _ in range(random.randint(1, 5)):
        toks += [random.choice("+-×÷"), str(random.randint(1, 50))]
    py = "".join({"×": "*", "÷": "/"}.get(t, t) if not t.isdigit() else f"F({t})" for t in toks)
    assert bodmas(toks) == eval(py)

from fractions import Fraction as F
import re

def tokens(expr):
    expr = expr.replace("−", "-").replace("–", "-").replace("x", "×").replace("/", "÷")
    return re.findall(r"\d+|[+\-×÷]", expr)

def bodmas(toks):
    """Division and multiplication left to right, then addition and subtraction left to right."""
    out = [F(toks[0])]
    for op, n in zip(toks[1::2], toks[2::2]):
        n = F(n)
        if op == "×":
            out[-1] *= n
        elif op == "÷":
            out[-1] /= n
        else:
            out += [op, n]
    val = out[0]
    for op, n in zip(out[1::2], out[2::2]):
        val = val + n if op == "+" else val - n
    return val

def swap_signs(toks, pairs):
    m = {}
    for a, b in pairs:
        m[a], m[b] = b, a
    return [m.get(t, t) for t in toks]

def swap_numbers(toks, a, b):
    m = {a: b, b: a}
    return [m.get(t, t) for t in toks]

def balanced(toks, rhs):
    return bodmas(toks) == rhs

def solve_numbers(expr, rhs, options):
    t = tokens(expr)
    return [k for k, (a, b) in options.items() if balanced(swap_numbers(t, a, b), rhs)]

def solve_signs(expr, rhs, options):
    t = tokens(expr)
    return [k for k, (a, b) in options.items() if balanced(swap_signs(t, [(a, b)]), rhs)]

